            // Therefore we must use from_borrowed_ptr instead of from_owned_ptr so that the
            // GILPool does not take ownership of the reference.
            Ok(PyIterator(py.from_borrowed_ptr(ptr)))
        } else {
            Err(PyDowncastError)
        }
    }

